import os
import subprocess

def _git(root, *arguments):
    return subprocess.run(['git', '-C', str(root), *arguments], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, env={**os.environ, 'GIT_CONFIG_GLOBAL': os.devnull, 'GIT_CONFIG_NOSYSTEM': '1'}).stdout.strip()

import os
import subprocess

def _git(root, *arguments):
    return subprocess.run(['git', '-C', str(root), '-c', 'maintenance.auto=false', '-c', 'gc.auto=0', *arguments], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, env={**os.environ, 'GIT_CONFIG_GLOBAL': os.devnull, 'GIT_CONFIG_NOSYSTEM': '1'}).stdout.strip()

def test_git_disables_maintenance(monkeypatch, tmp_path):
    from types import SimpleNamespace
    calls = []

    def capture(command, **options):
        calls.append((command, options))
        return SimpleNamespace(stdout='ok')
    monkeypatch.setattr(subprocess, 'run', capture)
    assert _git(tmp_path, 'status') == 'ok'
    command, options = calls[0]
    assert ('-c', 'maintenance.auto=false', '-c', 'gc.auto=0') == tuple(command[3:7]), 'automatic maintenance remains enabled'
    assert options['env']['GIT_CONFIG_GLOBAL'] == os.devnull
    assert options['env']['GIT_CONFIG_NOSYSTEM'] == '1'

